tool_calls:
cat /data/commits.log; mkdir -p /release; awk '
match($0, /^([^ (]+)\(([^)]+)\): (.*)$/, a) {
  type=a[1]; scope=a[2]; message=a[3]
  if (type == "feat") section="Features"
  else if (type == "fix") section="Bug Fixes"
  else section="Other"
  if (!seen[section]++) {
    order[++n]=section
  }
  items[section]=items[section] "- " scope ": " message "\n"
}
END {
  for (i=1; i<=n; i++) {
    section=order[i]
    if (section == "Features") header="## Features"
    else if (section == "Bug Fixes") header="## Bug Fixes"
    else header="## Other"
    printf "%s\n%s", header, items[section]
    if (i<n) printf "\n"
  }
}' /data/commits.log > /release/CHANGELOG.md
cat /release/CHANGELOG.md

